module tb;
    reg clk;
    reg load;
    reg ena;
    reg [1:0] amount;
    reg [63:0] data;
    wire [63:0] q;

    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .amount(amount),
        .data(data),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        load = 0;
        ena = 0;
        amount = 2'b00;
        data = 64'h0;

        @(posedge clk);
        // Test load
        load = 1;
        data = 64'h8000000000000001; // MSB = 1
        @(posedge clk);
        load = 0;
        if (q !== 64'h8000000000000001) begin
            $display("SELFTEST FAIL: Load failed. Got %h", q);
            $finish;
        end

        // Test shift left by 1
        ena = 1;
        amount = 2'b00;
        @(posedge clk);
        if (q !== 64'h0000000000000002) begin
            $display("SELFTEST FAIL: Shift left 1 failed. Got %h", q);
            $finish;
        end

        // Test load positive number
        load = 1;
        data = 64'h0F00000000000000;
        @(posedge clk);
        load = 0;

        // Test shift right by 1 (arithmetic, MSB=0)
        amount = 2'b10;
        @(posedge clk);
        if (q !== 64'h0780000000000000) begin
            $display("SELFTEST FAIL: Shift right 1 (positive) failed. Got %h", q);
            $finish;
        end

        // Test load negative number for arithmetic right shift
        load = 1;
        data = 64'hF000000000000000;
        @(posedge clk);
        load = 0;

        // Test shift right by 8 (amount = 2'b11), MSB=1 -> should fill with 1s
        amount = 2'b11;
        @(posedge clk);
        if (q !== 64'hFFF0000000000000) begin
            $display("SELFTEST FAIL: Shift right 8 (negative) failed. Got %h", q);
            $finish;
        end

        // Test shift left by 8 (amount = 2'b01)
        load = 1;
        data = 64'h0123456789ABCDEF;
        @(posedge clk);
        load = 0;

        amount = 2'b01;
        @(posedge clk);
        if (q !== 64'h23456789ABCDEF00) begin
            $display("SELFTEST FAIL: Shift left 8 failed. Got %h", q);
            $finish;
        end

        // Test ena = 0 holds state
        ena = 0;
        amount = 2'b00;
        @(posedge clk);
        if (q !== 64'h23456789ABCDEF00) begin
            $display("SELFTEST FAIL: Ena=0 hold state failed. Got %h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

